import { z } from "zod";
import { safeDownloadName, UPLOAD_BYTES } from "./quarantine.ts";

// The chooser identity is generated by browserd. CDP node IDs, frame IDs and
// browser filesystem paths never cross this boundary.
export const BrowserUploadChooser = z.strictObject({
  id: z.uuid(),
  mode: z.enum(["single", "multiple"]),
});
export type BrowserUploadChooser = z.infer<typeof BrowserUploadChooser>;

// This is the document receiving File objects, not a promise about where that
// document may subsequently send them. Never expose URL paths or query strings.
export const BrowserUploadDestination = z.strictObject({
  origin: z
    .string()
    .min(1)
    .max(512)
    .refine((value) => {
      try {
        const url = new URL(value);
        return (url.protocol === "https:" || url.protocol === "http:") && url.origin === value;
      } catch {
        return false;
      }
    }),
  embedded: z.boolean(),
});
export type BrowserUploadDestination = z.infer<typeof BrowserUploadDestination>;
export const BrowserUploadOffer = BrowserUploadChooser.extend(BrowserUploadDestination.shape);
export type BrowserUploadOffer = z.infer<typeof BrowserUploadOffer>;

export const BrowserUploadFile = z.strictObject({
  name: z
    .string()
    .min(1)
    .max(180)
    .refine((value) => value === safeDownloadName(value)),
  bytes: z.number().int().nonnegative().max(UPLOAD_BYTES),
  sha256: z.string().regex(/^[0-9a-f]{64}$/u),
});
export type BrowserUploadFile = z.infer<typeof BrowserUploadFile>;
export const BrowserUploadFiles = BrowserUploadFile.array()
  .min(1)
  .max(10)
  .refine((files) => files.reduce((total, file) => total + file.bytes, 0) <= UPLOAD_BYTES);
